import React, { useState } from 'react';
import type { CCSearchItem } from '@cloud-materials/common';
import { Card, CConfigProvider, CRadio, CSearch } from '@cloud-materials/common';
import zhCN from '@cloud-materials/common/es/locales/zh-CN';
import enUS from '@cloud-materials/common/es/locales/en-US';

const searchList: CCSearchItem[] = [
  {
    fieldName: 'Select',
    content: {
      component: 'Select',
      componentProps: {
        options: [
          {
            label: '专科',
            value: 'junior',
          },
          {
            label: '本科',
            value: 'undergraduate',
          },
        ],
      },
    },
    colspan: 6,
  },
  {
    fieldName: 'Input',
    content: {
      component: 'Input',
    },
    colspan: 6,
  },
  {
    fieldName: 'RangePicker',
    content: {
      component: 'RangePicker',
    },
    colspan: 6,
  },
];

export default () => {
  const [locale, setLocale] = useState('zh-CN');

  const getLocale = () => {
    return locale === 'en-US' ? enUS : zhCN;
  };

  return (
    <CConfigProvider cPrefixCls="c-m" prefixCls="arco" locale={getLocale()}>
      <CRadio.Group options={['zh-CN', 'en-US']} value={locale} onChange={setLocale} />
      <Card style={{ marginTop: 24 }}>
        <CSearch list={searchList} displayCount={1} manual showAdvanceReset showReset />
      </Card>
    </CConfigProvider>
  );
};

